from pathlib import Path
p=Path('internal/server/users_query_integration_test.go')
s=p.read_text().replace('\"context\"','\"context\"\\n\\t\"fmt\"').replace('\"os\"','\"os\"\\n\\t\"slices\"').replace('\"testing\"','\"testing\"\\n\\t\"time\"')
s+='''
// This test drops both schemas; use a dedicated disposable database and do not
// run other integration test processes against it concurrently.
func TestListUsersPaginationHasStableOrder(t *testing.T) {
	dsn := os.Getenv(\"TEST_POSTGRES_DSN\")
	if dsn == \"\" {
		t.Skip(\"TEST_POSTGRES_DSN is not set\")
	}
	ctx := context.Background()
	db, err := database.Open(ctx, dsn)
	if err "'!= nil {
		t.Fatal(err)
	}
	defer db.Close()
	if _, err := db.Pool.Exec(ctx, `DROP SCHEMA IF EXISTS ai_admin CASCADE; DROP SCHEMA IF EXISTS aiportal CASCADE`); err != nil {
		t.Fatal(err)
	}
	if err := db.Migrate(ctx); err != nil {
		t.Fatal(err)
	}
	if err := db.Seed(ctx, "admin@example.com", "integration-password"); err != nil {
		t.Fatal(err)
	}
	cipher, err := secrets.New(bytes.Repeat([]byte{7}, 32))
	if err != nil {
		t.Fatal(err)
	}
	handler := New(db, cipher, slog.New(slog.NewTextHandler(io.Discard, nil))).Handler()
	admin := signIn(t, handler)

	created := time.Date(2026, 1, 2, 0, 0, 0, 0, time.UTC)
	var adminID string
	if err := db.Pool.QueryRow(ctx, `UPDATE ai_admin.app_user SET created_at=$1 WHERE username='"'admin@example.com' RETURNING id"'`, created.Add(-2*time.Hour)).Scan(&adminID); err != nil {
		t.Fatal(err)
	}
	id := func(n int) string { return fmt.Sprintf("00000000-0000-4000-8000-%012d", n) }
	// Six ties arrive in neither ascending nor descending UUID order. The
	// newest row has the smallest ID and the older row has the largest ID,
	// so sorting only by ID would also fail.
	for _, n := range []int{4, 2, 7, 3, 6, 5, 8, 1} {
		stamp := created
		if n == 1 {
			stamp = created.Add(time.Hour)
		} else if n == 8 {
			stamp = created.Add(-time.Hour)
		}
		if _, err := db.Pool.Exec(ctx, `INSERT INTO ai_admin.app_user(id,username,display_name,auth_source,status,created_at)
VALUES($1,$2,'"'pagination-order-fixture','local','active',"'$3)`, id(n), fmt.Sprintf("order-%d@example.com", n), stamp); err != nil {
			t.Fatal(err)
		}
	}
	fixtureIDs := []string{id(1), id(7), id(6), id(5), id(4), id(3), id(2), id(8)}
	for _, tc := range []struct {
		name string
		query string
		want []string
	}{
		{"filtered", "pagination-order-fixture", fixtureIDs},
		{"all", "", append(slices.Clone(fixtureIDs), adminID)},
	} {
		for _, pageSize := range []int{2, 3} {
			t.Run(fmt.Sprintf("%s/size=%d", tc.name, pageSize), func(t *testing.T) {
				var got []string
				seen := make(map[string]bool)
				pages := (len(tc.want) + pageSize - 1) / pageSize
				// Include the first out-of-range page to check total and empty data.
				for page := 1; page <= pages+1; page++ {
					target := fmt.Sprintf("/api/v1/users?page=%d&pageSize=%d", page, pageSize)
					if tc.query != "" {
						target += "&q=" + url.QueryEscape(tc.query)
					}
					response := admin.do(t, handler, http.MethodGet, target, nil).Result()
					if response.StatusCode != http.StatusOK {
						t.Fatalf("page=%d status=%d body=%s", page, response.StatusCode, readBody(response))
					}
					var envelope struct {
						Data []struct { ID string `json:"id"` } `json:"data"`
						Page struct {
							Page int `json:"page"`
							PageSize int `json:"pageSize"`
							Total int `json:"total"`
						} `json:"page"`
					}
					decodeResponse(t, response, &envelope)
					if envelope.Page.Page != page || envelope.Page.PageSize != pageSize || envelope.Page.Total != len(tc.want) {
						t.Fatalf("page=%d metadata=%+v want pageSize=%d total=%d", page, envelope.Page, pageSize, len(tc.want))
					}
					var pageIDs []string
					for _, user := range envelope.Data {
						if seen[user.ID] {
							t.Fatalf("duplicate ID %s on page %d", user.ID, page)
						}
						seen[user.ID] = true
						pageIDs = append(pageIDs, user.ID)
					}
					start := min((page-1)*pageSize, len(tc.want))
					end := min(start+pageSize, len(tc.want))
					if !slices.Equal(pageIDs, tc.want[start:end]) {
						t.Fatalf("page=%d IDs=%v want=%v", page, pageIDs, tc.want[start:end])
					}
					got = append(got, pageIDs...)
				}
				if !slices.Equal(got, tc.want) {
					t.Fatalf("combined IDs=%v want=%v", got, tc.want)
				}
			})
		}
	}
}
'"'''
